const CACHE = 'analyseur-v3';

// Icons as base64 — served with correct image/png content-type
const ICON_192_B64 = '';
const ICON_512_B64 = '';

function b64toBlob(b64, type) {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return new Response(bytes, { headers: { 'Content-Type': type } });
}

const ASSETS = [
  './',
  './index.html',
  './manifest.json',
  'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js',
  'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js'
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(ASSETS)).catch(() => {}));
  self.skipWaiting();
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys =>
    Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))
  ));
  self.clients.claim();
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);

  // Intercept icon requests — serve with proper image/png content-type
  if (url.pathname.endsWith('icon-192.png')) {
    e.respondWith(b64toBlob(ICON_192_B64, 'image/png'));
    return;
  }
  if (url.pathname.endsWith('icon-512.png')) {
    e.respondWith(b64toBlob(ICON_512_B64, 'image/png'));
    return;
  }

  // Share target POST
  if (e.request.method === 'POST' && url.pathname.includes('/analytics/')) {
    e.respondWith((async () => {
      const data = await e.request.formData();
      const file = data.get('file');
      const clients = await self.clients.matchAll();
      if (clients[0] && file) clients[0].postMessage({ type: 'shared-file', file });
      return Response.redirect('/analytics/', 303);
    })());
    return;
  }

  // Cache-first for everything else
  e.respondWith(
    caches.match(e.request).then(cached => {
      if (cached) return cached;
      return fetch(e.request).then(res => {
        if (res && res.status === 200 && e.request.method === 'GET') {
          const clone = res.clone();
          caches.open(CACHE).then(c => c.put(e.request, clone));
        }
        return res;
      }).catch(() => cached || new Response('Offline', { status: 503 }));
    })
  );
});
